package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.articles.EntityDedupService.Decision;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;

class EntityHeatCutoffProofTest {
    EntityHeatEventAvailabilityTest h;JdbcEntityHeatCutoffUniverse universe;EntityHeatCutoffProofService service;final Instant cutoff=Instant.parse("2026-01-02T21:00:00Z");
    GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreTest();}
    @BeforeEach void setup(){h=new EntityHeatEventAvailabilityTest(){@Override GenerationJdbcStoreTest fixture(){return EntityHeatCutoffProofTest.this.fixture();}};h.setup();universe=new JdbcEntityHeatCutoffUniverse(h.h.h.f.source);service=create(EntityHeatCutoffProofService.MAX_ORIGINAL_BYTES);}
    EntityHeatCutoffProofService create(int budget){return new EntityHeatCutoffProofService(universe,h.events,h.service,new DataSourceTransactionManager(h.h.h.f.source),budget);}
    String append(String key,long revision,long count,Instant time){h.h.h.write(()->{h.h.h.f.jdbc.update("UPDATE analyzed_entities SET occurrence_count=?,revision=? WHERE id='fictional-new'",count,revision);new EntityDecisionJdbcLog(new JdbcEntityDecisions(h.h.h.f.source),"fictional-owner",Clock.fixed(time,ZoneOffset.UTC),h.h.h.snapshots).append(key,h.h.h.hash,new Decision("fictional-item","fictional-new","ready",true,count),"existing","fictional-item",null,"fictional-new","Fictional count history");return true;});return h.h.h.f.jdbc.queryForObject("SELECT id FROM jobs WHERE target_type='entity_decision' AND reason='Fictional count history' ORDER BY revision,id LIMIT 1",String.class);}
    @Test void CompleteNativeUniverseKeepsUnknownHistoricalHeadAndExactPastCountWithoutRanking(){h.service.capture(h.h.id);var value=service.capture(cutoff);assertEquals(Set.of("fictional-new"),value.counts().keySet());assertEquals(1,value.counts().get("fictional-new").snapshot().occurrenceCount());assertEquals(List.of(new EntityHeatCutoffProofService.Gap("fictional-old","count_missing")),value.gaps());assertEquals(cutoff,value.cutoff());assertSame(value,h.h.rr(()->service.verifyObserved(value)));assertThrows(UnsupportedOperationException.class,()->value.counts().clear());assertThrows(UnsupportedOperationException.class,()->value.gaps().clear());assertFalse(value.toString().contains("fictional"));assertEquals(0,h.h.h.f.count("record_kind='ai_attempt' OR record_kind='logical_task'"));}
    @Test void LaterNativeCountAfterTheCutoffCannotReplaceTheOriginalCount(){h.service.capture(h.h.id);String later=append("fictional-future",4,19,cutoff.plusSeconds(1));h.observer(Clock.fixed(cutoff.plusSeconds(2),ZoneOffset.UTC),h.h.h.f.writes).capture(later);var value=service.capture(cutoff);assertEquals(19,h.h.h.f.jdbc.queryForObject("SELECT occurrence_count FROM analyzed_entities WHERE id='fictional-new'",Long.class));assertEquals(1,value.counts().get("fictional-new").snapshot().occurrenceCount());assertEquals(h.h.id,value.counts().get("fictional-new").eventId());}
    @Test void UnknownOrLateFirstOnAnyPastCountEventPreventsFallbackToAnOlderCount(){h.service.capture(h.h.id);String next=append("fictional-late",4,7,cutoff.minusSeconds(1));var unknown=service.capture(cutoff);assertFalse(unknown.counts().containsKey("fictional-new"));assertTrue(unknown.gaps().contains(new EntityHeatCutoffProofService.Gap("fictional-new","count_unobserved_at_cutoff")));h.observer(Clock.fixed(cutoff.plusNanos(1000),ZoneOffset.UTC),h.h.h.f.writes).capture(next);var late=service.capture(cutoff);assertEquals(unknown.gaps(),late.gaps());assertFalse(late.counts().containsKey("fictional-new"));}
    @Test void ExactCutoffFirstQualifiesAndHigherOriginalRevisionSelectsActualFullSnapshot(){h.service.capture(h.h.id);String next=append("fictional-exact",4,8,cutoff.minusSeconds(1));h.observer(Clock.fixed(cutoff,ZoneOffset.UTC),h.h.h.f.writes).capture(next);var value=service.capture(cutoff);assertEquals(8,value.counts().get("fictional-new").snapshot().occurrenceCount());assertEquals(4,value.counts().get("fictional-new").snapshot().revision());assertEquals(cutoff,value.counts().get("fictional-new").availableAt());}
    @Test void V1LegacyNullAndMissingEntitiesNeverBecomeInventedCounts(){h.h.h.f.jdbc.update("DELETE FROM jobs");h.h.h.write(()->{new EntityDecisionJdbcLog(new JdbcEntityDecisions(h.h.h.f.source),"fictional-owner",h.h.h.f.clock).append("fictional-key",h.h.h.hash,new Decision("fictional-item","fictional-new","ready",true,1L),"new","fictional-item",null,"fictional-new","Fictional legacy");return true;});var old=service.capture(cutoff);assertTrue(old.counts().isEmpty());assertTrue(old.gaps().contains(new EntityHeatCutoffProofService.Gap("fictional-new","count_history_incomplete")));setup();h.h.h.f.jdbc.update("UPDATE analyzed_entities SET legacy_flag=1 WHERE id='fictional-new'");h.h.h.f.jdbc.update("DELETE FROM jobs");h.h.h.write(()->{h.h.h.save(new Decision("fictional-item","fictional-new","ready",true,1L),"new",null,"fictional-new");return true;});h.service.capture(h.h.id);assertTrue(service.capture(cutoff).gaps().contains(new EntityHeatCutoffProofService.Gap("fictional-new","count_legacy_unproven")));setup();h.service.capture(h.h.id);h.h.h.f.jdbc.update("DELETE FROM analyzed_entities");assertEquals(1,service.capture(cutoff).counts().get("fictional-new").snapshot().occurrenceCount());}
    @Test void EveryPageIsRetainedAndTheBudgetCannotSilentlyTruncateTheUniverse(){for(int i=0;i<130;i++)h.h.h.entity(String.format("fictional-head-%03d",i),1);h.service.capture(h.h.id);var value=service.capture(cutoff);assertEquals(131,value.gaps().size());assertTrue(value.originalByteSize()>130*256);assertThrows(RuntimeException.class,()->create(1024).capture(cutoff));}
    @Test void ConflictingSameRevisionAndDamagedNativeEventFailRatherThanHideTheCandidate(){h.service.capture(h.h.id);String other=append("fictional-conflict",3,7,cutoff.minusSeconds(1));h.observer(Clock.fixed(cutoff,ZoneOffset.UTC),h.h.h.f.writes).capture(other);assertThrows(RuntimeException.class,()->service.capture(cutoff));setup();h.service.capture(h.h.id);h.h.h.f.jdbc.update("UPDATE jobs SET revision=1 WHERE id=?",h.h.id);assertThrows(RuntimeException.class,()->service.capture(cutoff));}
    @Test void SameIssuerSameRrRechecksTheWholeUniverseAndAllNativeOriginals(){h.service.capture(h.h.id);var value=service.capture(cutoff);h.h.h.entity("fictional-added-head",1);assertThrows(RuntimeException.class,()->h.h.rr(()->service.verifyObserved(value)));setup();h.service.capture(h.h.id);var original=service.capture(cutoff);assertThrows(RuntimeException.class,()->h.h.rr(()->create(EntityHeatCutoffProofService.MAX_ORIGINAL_BYTES).verifyObserved(original)));h.h.h.f.jdbc.update("UPDATE jobs SET reason='Fictional changed origin' WHERE id=?",h.h.id);assertThrows(RuntimeException.class,()->h.h.rr(()->service.verifyObserved(original)));}
    @Test void FixedFiveOClockCutoffAndExplicitReadonlyRrAreMandatory(){assertThrows(RuntimeException.class,()->service.capture(cutoff.plusNanos(1000)));assertThrows(RuntimeException.class,()->service.capture(cutoff.plusSeconds(1)));assertThrows(RuntimeException.class,()->h.h.rr(()->service.capture(cutoff)));assertThrows(RuntimeException.class,()->universe.heads("",cutoff,64));var tx=new TransactionTemplate(new DataSourceTransactionManager(h.h.h.f.source));tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);assertThrows(RuntimeException.class,()->tx.execute(s->universe.events("",cutoff,64)));assertThrows(RuntimeException.class,()->h.h.h.write(()->universe.heads("",cutoff,64)));}
    @Test void NativeCutoffPortsAreColdAndMandatory(){var source=mock(javax.sql.DataSource.class);var tx=mock(PlatformTransactionManager.class);var events=mock(EntityHeatEventProofService.class);var first=mock(EntityHeatEventAvailabilityService.class);new EntityHeatCutoffProofService(new JdbcEntityHeatCutoffUniverse(source),events,first,tx);verifyNoInteractions(source,tx,events,first);assertThrows(NullPointerException.class,()->new EntityHeatCutoffProofService(universe,null,h.service,tx));}
    @Test void CompleteOriginalEventFactsRetainUnobservedPastEventsAndExcludeFutureEvents(){h.service.capture(h.h.id);append("fictional-past-source",4,2,cutoff.minusSeconds(1));append("fictional-future-source",5,3,cutoff.plusSeconds(1));var value=service.capture(cutoff);assertEquals(2,value.originalEvents().size());assertFalse(value.counts().containsKey("fictional-new"));assertTrue(value.originalEvents().stream().anyMatch(e->e.id().equals(h.h.id)));for(var event:value.originalEvents()){assertFalse(event.actedAt().isAfter(cutoff));assertNotNull(event.payloadJson());assertNotNull(event.targetJson());assertNotNull(event.reason());assertEquals(event.payloadHash(),HexFormat.of().formatHex(JdbcGenerationLineage.hash(event.payloadJson())));}assertThrows(UnsupportedOperationException.class,()->value.originalEvents().clear());assertSame(value,h.h.rr(()->service.verifyObserved(value)));h.h.h.f.jdbc.update("UPDATE jobs SET reason='Fictional source origin changed' WHERE id=?",h.h.id);assertThrows(RuntimeException.class,()->h.h.rr(()->service.verifyObserved(value)));}
    @Test void FullPastEventPagesRemainAvailableEvenWhenCountsCannotQualify(){for(int i=0;i<130;i++)append("fictional-history-page-"+i,4+i,2+i,cutoff.minusSeconds(1));var value=service.capture(cutoff);assertEquals(131,value.originalEvents().size());assertEquals(131,value.originalEvents().stream().map(JdbcEntityHeatEvents.Event::id).distinct().count());assertTrue(value.counts().isEmpty());assertTrue(value.originalByteSize()>131*512);assertThrows(RuntimeException.class,()->create(1024).capture(cutoff));}
}
